// src/components/MyVotesPage.js
import { useEffect, useState } from "react";
import axios from "axios";

const API_URL = "http://localhost:5000";

function MyVotesPage({ auth }) {
  const [votes, setVotes] = useState([]);

  useEffect(() => {
    const fetchVotes = async () => {
      try {
        const res = await axios.get(`${API_URL}/api/vote/my`, {
          headers: { Authorization: `Bearer ${auth.token}` },
        });
        setVotes(res.data);
      } catch (err) {
        console.error("Failed to fetch votes", err);
      }
    };

    fetchVotes();
  }, [auth.token]);

  return (
    <div style={{ padding: 20 }}>
      <h1>My Vote History</h1>
      {votes.length === 0 && <p>You haven’t voted yet.</p>}
      <ul style={{ listStyle: "none", padding: 0 }}>
        {votes.map((v, i) => (
          <li
            key={i}
            style={{
              display: "flex",
              alignItems: "center",
              marginBottom: 15,
              backgroundColor: "#fff",
              padding: 10,
              borderRadius: 8,
              boxShadow: "0 2px 6px rgba(0,0,0,0.08)",
            }}
          >
            {v.image ? (
              <img
                src={`${API_URL}/uploads/${v.image}`}
                alt={v.candidateName}
                style={{
                  width: 50,
                  height: 50,
                  borderRadius: "50%",
                  marginRight: 15,
                  objectFit: "cover",
                }}
              />
            ) : (
              <div
                style={{
                  width: 50,
                  height: 50,
                  borderRadius: "50%",
                  backgroundColor: "#ccc",
                  marginRight: 15,
                }}
              />
            )}
            <div>
              <strong>{v.position}</strong>
              <p style={{ margin: 0 }}>{v.candidateName}</p>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default MyVotesPage;
